@paginate(pagination_model=PAGINATION_MODEL)  # type: ignore[misc]
def list_groups(self, identity_store_id: str, filters: List[Dict[str, str]] = None) -> List[Group]:
    identity_store = self.__get_identity_store(identity_store_id)

    groups = []
    if filters:
        if filters[0].get("AttributePath") == "DisplayName":
            display_name = filters[0].get("AttributeValue")

            for g in identity_store.groups.values():
                if g.DisplayName == display_name:
                    groups.append(g)
            return groups

    return list(identity_store.groups.values())
